def reprendre_existant(apps, schema_editor):
    """
    Les responsables déjà désignés d'étapes de circuits confidentiels (hors Administrateurs, qui ont
    l'accès d'office) sont habilités d'office ; chaque reprise est inscrite au journal d'audit.
    """
    from django.utils import timezone

    EtapeCircuit = apps.get_model("plaintes", "EtapeCircuit")
    Habilitation = apps.get_model("plaintes", "HabilitationSensible")
    Evenement = apps.get_model("core", "EvenementAudit")
    personnes = {e.responsable for e in EtapeCircuit.objects.filter(circuit__sensible=True, responsable__isnull=False)
                 .select_related("responsable") if e.responsable.role != "ADMIN"}
    maintenant = timezone.now()
    for personne in sorted(personnes, key=lambda p: p.pk):
        h = Habilitation.objects.create(
            utilisateur=personne, statut="ACTIVE", date_validation=maintenant, active_le=maintenant,
            motif="Reprise de l'existant : responsable d'étape d'un circuit confidentiel avant la double validation.",
        )
        nom = f"{personne.first_name} {personne.last_name}".strip()
        Evenement.objects.create(utilisateur_id=None, utilisateur="", action="HABILITATION", module="plaintes",
                                 objet=(f"{nom} ({personne.username})" if nom else personne.username)[:255],
                                 details={"operation": "reprise_existant", "habilitation": h.pk})


